class Solution {
  public int[] minCost(int[] nums, int[][] queries) {
    int n = nums.length;
    long[] right = new long[n], left = new long[n];
    for (int i = 0; i + 1 < n; i++) {
      long diff = (long) nums[i + 1] - nums[i];
      int closest = i == 0 ? 1 : (nums[i + 1] - nums[i] < nums[i] - nums[i - 1] ? i + 1 : i - 1);
      right[i + 1] = right[i] + (closest == i + 1 ? 1 : diff);
    }
    for (int i = n - 1; i >= 1; i--) {
      long diff = (long) nums[i] - nums[i - 1];
      int closest =
          i == n - 1 ? n - 2 : (nums[i + 1] - nums[i] < nums[i] - nums[i - 1] ? i + 1 : i - 1);
      left[i - 1] = left[i] + (closest == i - 1 ? 1 : diff);
    }
    int[] ans = new int[queries.length];
    for (int q = 0; q < queries.length; q++) {
      int l = queries[q][0], r = queries[q][1];
      ans[q] = (int) (l <= r ? right[r] - right[l] : left[r] - left[l]);
    }
    return ans;
  }
}
